+                queue.enqueue_with_backpressure_warning_outcome(make_ticket(i));
+            assert_eq!(
+                bp_outcome,
+                BackpressureWarningOutcome::Delivered,
+                "before threshold: Delivered (no send attempted)"
+            );
+        }
