current-source:302: /// Uses checked arithmetic; if `capacity * 8` would overflow `usize`, the function
current-source:303: /// falls back to `capacity` itself (which is already > the would-be threshold
current-source:304: /// in any realistic capacity that could overflow).
current-source:305: fn backpressure_threshold(capacity: ActionQueueCapacity) -> usize {
current-source:306:     let raw = capacity.get();
current-source:307:     // INVARIANT: ceiling division `ceil(raw * 8 / 10) = (raw * 8 + 9) / 10` is
current-source:308:     // computed via checked arithmetic so that capacity values near `usize::MAX / 8`
current-source:309:     // cannot wrap. On overflow we return `raw` (the original capacity) which is
current-source:310:     // always >= any valid threshold for inputs the queue can hold.
current-source:311:     let threshold = usize::checked_mul(raw, 8)
current-source:312:         .and_then(|scaled| usize::checked_add(scaled, 9))
current-source:313:         .and_then(|numerator| usize::checked_div(numerator, 10));
current-source:314:     match threshold {
current-source:315:         Some(value) => value.max(1),
current-source:316:         None => raw,
current-source:317:     }
current-source:318: }
